/* ============================================================
   FLUENT PATH — PÁGINAS 2
   Speaking, Listening, Reading, Writing, Mistakes, Review,
   Progress, Roadmap, AI Tutor, Achievements, Settings, Tracks.
   ============================================================ */
const single = (item, reason) => { item.block = 'q'; item.reason = reason; startRunner({ items: [item], blocks: [{ key: 'q', label: 'Practice', items: [item] }], quick: true }, { kind: 'quick' }); };
const dateShort = t => new Date(t).toLocaleDateString('en-GB', { day: 'numeric', month: 'short' });

/* ---------------------- SPEAKING ---------------------- */
let SP = { tab: 'prompts', lvl: '' }; let PRN = null;
route(/^\/speaking$/, () => {
  const spk = S.analyses.filter(a => a.src === 'speak');
  const prompts = CONTENT.spk.filter(p => !SP.lvl || p.lvl === SP.lvl);
  let body = '';
  if (SP.tab === 'prompts') body = `<div class="row wrap" style="margin-bottom:14px">${[['', 'All'], ['B1', 'B1'], ['B1+', 'B1+'], ['B2', 'B2'], ['B2+', 'B2+']].map(([v, l]) => `<button class="chip ${SP.lvl === v ? 'on' : ''}" data-a="splvl" data-v="${v}">${l}</button>`).join('')}<button class="chip" data-a="quick" data-m="speaking" data-min="3">${I('shuffle')} Surprise me</button></div><div class="grid g2">${prompts.map(p => `<div class="card flat click" data-a="spstart" data-id="${p.id}"><div class="row between"><span class="small muted">${esc(p.topic)}</span>${lvTag(p.lvl)}</div><p class="b" style="margin-top:8px;font-size:1.02rem">${esc(p.prompt)}</p><div class="tiny muted" style="margin-top:8px">${p.goals.slice(0, 2).map(esc).join(' · ')}</div></div>`).join('')}</div>`;
  else if (SP.tab === 'roleplay') body = `<p class="muted" style="margin-bottom:14px">Complete scenarios with hidden objectives (past tense, explain a cause, propose a solution…). A character answers you; at the end you see what you achieved.</p><div class="grid g2">${CONTENT.rp.map(r => `<div class="card flat click" data-a="rpstart" data-id="${r.id}"><div class="row"><div class="ico acc">${I(topicIcon[r.topic] || 'globe')}</div><div class="grow"><b>${esc(r.title)}</b><div class="small muted">${esc(r.persona)}</div></div>${lvTag(r.lvl)}</div><p class="small muted" style="margin-top:10px">${esc(r.situation)}</p><div class="tiny muted" style="margin-top:8px">${r.objectives.length} hidden objectives</div></div>`).join('')}</div>`;
  else if (SP.tab === 'pron') body = pronHTML();
  else body = spk.length ? `<div class="grid g2" style="margin-bottom:16px"><div class="card"><h4>Estimated speaking level</h4>${lineChart(spk.slice(-12).map(a => a.levelIdx), { min: 1, max: 5, h: 130, fmt: v => lvLabel(v) })}</div><div class="card"><h4>Latest scores</h4>${['grammar', 'vocabulary', 'naturalness', 'clarity', 'connectors'].map(k => `<div class="score-row"><span>${k[0].toUpperCase() + k.slice(1)}</span>${bar(avg(spk.slice(-5).map(a => a.scores[k])) / 100)}<b>${Math.round(avg(spk.slice(-5).map(a => a.scores[k])))}%</b></div>`).join('')}</div></div><div class="card"><div class="list">${spk.slice().reverse().slice(0, 12).map(a => `<div class="it"><div class="grow"><div class="b small">${esc(a.prompt || 'Speaking')}</div><div class="tiny muted">${dateShort(a.at)} · ${a.words} words${a.wpm ? ' · ' + a.wpm + ' wpm' : ''}</div></div>${lvTag(a.cefr)}</div>`).join('')}</div></div>` : `<div class="empty">No speaking history yet. Start with a prompt.</div>`;
  return { html: `<div class="ph"><div><h1>Speaking</h1><p>Spontaneous answers, roleplay and pronunciation. You speak; the browser transcribes; the engine analyses fluency, grammar, vocabulary and naturalness.</p></div></div>${!Speech.sttOk ? `<div class="fb part" style="margin-bottom:14px">${I('alert')} Voice input needs Chrome or Edge. In other browsers you can type your answers.</div>` : ''}<div class="tabs">${[['prompts', 'Prompts'], ['roleplay', 'Roleplay'], ['pron', 'Pronunciation'], ['hist', 'History']].map(([t, n]) => `<button class="${SP.tab === t ? 'on' : ''}" data-a="sptab" data-t="${t}">${n}</button>`).join('')}</div>${body}` };
});
ACT.sptab = el => { SP.tab = el.dataset.t; render(); };
ACT.splvl = el => { SP.lvl = el.dataset.v; render(); };
ACT.spstart = el => single(speakItem(S, IDX.spk[el.dataset.id]), 'You chose this prompt.');
ACT.rpstart = el => startRoleplay(el.dataset.id);
function pronHTML() {
  if (!PRN) PRN = { list: shuffle(CONTENT.nat.map(n => n.natural).filter(t => { const w = tokens(t).length; return w >= 5 && w <= 12; })).slice(0, 12), i: 0, res: null };
  const t = PRN.list[PRN.i];
  return `<div class="grid g21"><div class="card"><div class="rlabel">${I('mic')} Read it aloud · ${PRN.i + 1}/${PRN.list.length}</div><div class="rsub" id="pt" style="margin-top:12px;font-size:1.4rem">${PRN.res ? PRN.res.words.map(w => `<span class="${w.ok ? 'hl-ok' : 'hl-bad'}">${esc(w.w)}</span>`).join(' ') : esc(t)}</div>
  <div class="row wrap" style="margin-top:14px"><button class="btn" data-a="prlisten">${I('volume')} Listen</button>${Speech.sttOk ? `<button class="btn primary" data-a="prrec" id="prb">${I('mic')} Record</button>` : '<span class="small muted">Recording needs Chrome/Edge.</span>'}<button class="btn ghost" data-a="prnext">Next ${I('arrow')}</button></div><div id="prres" style="margin-top:14px">${PRN.res ? prResHTML() : '<p class="small muted">Listen first, then read the sentence naturally. The browser’s speech recognition checks which words it understood — a good proxy for clear pronunciation.</p>'}</div></div>
  <div class="card"><h4>Tricky words</h4><div class="stack" style="margin-top:8px">${Object.keys(STRESS).map(w => `<div class="row small"><span class="grow"><b>${w}</b><div class="muted tiny">${STRESS[w]}</div></span>${sayBtn(w)}</div>`).join('')}</div></div></div>`;
}
const prResHTML = () => `<div class="score-row" style="grid-template-columns:120px 1fr 46px"><span>Clarity</span>${bar(PRN.res.score / 100, PRN.res.score >= 80 ? 'ok' : 'acc')}<b>${PRN.res.score}%</b></div>${PRN.res.words.filter(w => !w.ok).length ? `<p class="small" style="margin-top:6px">Not recognized: ${PRN.res.words.filter(w => !w.ok).map(w => `<b>${esc(w.w)}</b>${STRESS[w.w] ? ' (' + STRESS[w.w] + ')' : ''}`).join(', ')}. Say them slowly, stress the strong syllable, and try again.</p>` : '<p class="small" style="color:var(--ok);margin-top:6px">Every word was understood. Great clarity!</p>'}`;
ACT.prlisten = () => Speech.speak(PRN.list[PRN.i], { rate: .9, accent: S.settings.accent });
ACT.prnext = () => { PRN.i = (PRN.i + 1) % PRN.list.length; PRN.res = null; render(); };
ACT.prrec = () => { const b = $('#prb'); if (PRN.rec) { PRN.rec.stop(); PRN.rec = null; return; } b.classList.add('primary'); b.innerHTML = I('x') + ' Stop'; let heard = ''; PRN.rec = Speech.listen({ onText: t => heard = t, onEnd: () => { PRN.rec = null; if (heard) { PRN.res = comparePron(PRN.list[PRN.i], heard); applySkill(S, 'speaking', 3, PRN.res.score >= 80, .25); addMinutes(.4); saveSoon(); } render(); }, onError: e => { PRN.rec = null; toast(e === 'not-allowed' ? 'Microphone blocked.' : 'Could not record: ' + e, 'alert'); render(); } }); setTimeout(() => { if (PRN && PRN.rec) PRN.rec.stop(); }, 12000); };

/* ---------------------- LISTENING / READING ---------------------- */
let LS = { lvl: '', topic: '' };
function lisPage(mode) {
  const srcList = mode === 'read' && (CONTENT.rd || []).length ? CONTENT.rd : CONTENT.lis;
  const list = srcList.filter(l => (!LS.lvl || l.lvl === LS.lvl) && (!LS.topic || l.topic === LS.topic));
  const skill = mode === 'read' ? 'reading' : 'listening'; const topics = [...new Set(srcList.map(l => l.topic))];
  return `<div class="ph"><div><h1>${mode === 'read' ? 'Reading' : 'Listening lab'}</h1><p>${mode === 'read' ? 'Read short texts, then answer inference and vocabulary-in-context questions.' : 'Different speeds, accents and situations. The transcript appears only after you answer, so you really train your ear.'}</p></div><div class="row"><span class="pill">${I(mode === 'read' ? 'book' : 'headphones')} ${SKILL_NAME[skill]}: ${lvLabel(S.sk[skill].a)}</span>${mode === 'read' ? '' : `<button class="btn primary" data-a="quick" data-m="listening" data-min="3">${I('zap')} Quick listening</button>`}</div></div>
  ${mode === 'read' ? '' : `<div class="card flat row wrap" style="margin-bottom:14px"><span class="small b">Playback speed</span><div class="seg">${[.75, 1, 1.15, 1.25].map(s => `<button class="${S.settings.speed === s ? 'on' : ''}" data-a="setspeed" data-s="${s}">${s}×</button>`).join('')}</div><span class="small muted">Start slower if needed, then move toward natural speed.</span></div>`}
  <div class="row wrap" style="margin-bottom:14px">${[['', 'All'], ['B1', 'B1'], ['B1+', 'B1+'], ['B2', 'B2'], ['B2+', 'B2+']].map(([v, l]) => `<button class="chip ${LS.lvl === v ? 'on' : ''}" data-a="lsf" data-k="lvl" data-v="${v}" data-mode="${mode}">${l}</button>`).join('')}<span style="width:8px"></span>${[''].concat(topics).map(t => `<button class="chip ${LS.topic === t ? 'on' : ''}" data-a="lsf" data-k="topic" data-v="${t}" data-mode="${mode}">${t || 'All topics'}</button>`).join('')}</div>
  <div class="grid g2">${list.map(l => `<div class="card flat click" data-a="lsstart" data-id="${l.id}" data-mode="${mode}"><div class="row"><div class="ico">${I(mode === 'read' ? 'book' : 'headphones')}</div><div class="grow"><b>${l.title ? esc(l.title) : esc(TOPIC_LABEL[l.topic] || l.topic) + ' · ' + esc(l.kind)}</b><div class="small muted">${l.title ? esc(TOPIC_LABEL[l.topic] || l.topic) + ' · ' + esc(l.kind) + ' · ' : ''}${(l.script || l.text).split(/\s+/).length} words${mode === 'read' ? '' : ' · ' + l.speed + ' · ' + (l.accent === 'gb' ? 'British' : 'American')}</div></div>${lvTag(l.lvl)}</div>${(S.seenEx[l.id]) ? `<div class="tiny" style="color:var(--ok);margin-top:8px">✓ done ${ago(S.seenEx[l.id])}</div>` : ''}</div>`).join('') || '<div class="empty">No passages match.</div>'}</div>`;
}
route(/^\/listening$/, () => lisPage('listen'));
route(/^\/reading$/, () => lisPage('read'));
ACT.lsf = el => { LS[el.dataset.k] = el.dataset.v; render(); };
ACT.lsstart = el => { const id = el.dataset.id; if (IDX.rd[id]) single(readItem(S, IDX.rd[id]), 'You chose this text.'); else single(listenItem(S, IDX.lis[id], el.dataset.mode), 'You chose this passage.'); };
ACT.setspeed = el => { S.settings.speed = +el.dataset.s; save(); render(); };

/* ---------------------- WRITING LAB ---------------------- */
let WR = { type: 'Opinion', text: '', an: null, ai: null, t0: 0 };
const WR_TYPES = { Email: 'Write an email to a colleague explaining a delay in a project.', Message: 'Write a short message to a friend inviting them to a trip.', Opinion: 'Do you think AI will make IT jobs better or worse? Explain.', Story: 'Tell a short story about a day when everything went wrong.', Professional: 'Reply to a customer who is angry about a service outage.' };
route(/^\/writing$/, () => {
  const hist = S.analyses.filter(a => a.src === 'write');
  return { html: `<div class="ph"><div><h1>Writing lab</h1><p>Write freely. You get your estimated level, grammar, vocabulary, naturalness, connectors and concrete rewrites.</p></div></div>
  <div class="grid g21"><div class="stack"><div class="card"><div class="row wrap">${Object.keys(WR_TYPES).map(t => `<button class="chip ${WR.type === t ? 'on' : ''}" data-a="wrtype" data-t="${t}">${t}</button>`).join('')}</div><div class="rsub small" style="margin-top:12px">${I('bulb')} <span id="wrprompt">${esc(WR.prompt || (WR.prompt = wrPick(WR.type)))}</span> <button class="btn sm" style="margin-left:8px" data-a="wrnew">${I('refresh')} New topic</button></div><textarea id="wrt" placeholder="Start writing here…" style="min-height:220px;margin-top:12px;font-size:1.02rem">${esc(WR.text)}</textarea><div class="row between" style="margin-top:12px"><span class="small muted" id="wrc"></span><div class="row">${AIService.enabled() ? `<button class="btn" data-a="wrai">${I('sparkles')} AI review</button>` : ''}<button class="btn primary" data-a="wranalyze">${I('check')} Analyze</button></div></div></div><div id="wrres">${WR.an ? `<div class="card"><h3 style="margin-bottom:10px">Your analysis</h3>${analysisHTML(WR.an, [])}${WR.ai ? aiBlock(WR.ai) : ''}</div>` : ''}</div></div>
  <div class="stack"><div class="card"><h4>Writing level over time</h4>${hist.length >= 2 ? lineChart(hist.slice(-10).map(a => a.levelIdx), { min: 1, max: 5, h: 130, fmt: v => lvLabel(v) }) : '<p class="small muted" style="margin-top:6px">Analyze two or more texts to see your trend.</p>'}</div>
  <div class="card"><h4>Writing challenges</h4><div class="stack" style="margin-top:8px">${wrChallenges().map(c => `<button class="btn sm" style="justify-content:flex-start;text-align:left;white-space:normal" data-a="wrchal" data-id="${c.id}">${esc(c.prompt)} ${lvTag(c.lvl)}</button>`).join('')}</div></div></div></div>`, after: () => { const t = $('#wrt'); const c = () => { const an = analyzeText(t.value); $('#wrc').textContent = an.words + ' words · ' + an.sentences + ' sentences'; WR.text = t.value; }; t.addEventListener('input', c); c(); WR.t0 = WR.t0 || Date.now(); } };
});
ACT.wrtype = el => { WR.text = $('#wrt') ? $('#wrt').value : WR.text; WR.type = el.dataset.t; WR.prompt = wrPick(WR.type); WR.an = null; render(); };
ACT.wrnew = () => { WR.text = $('#wrt') ? $('#wrt').value : WR.text; WR.prompt = wrPick(WR.type); WR.an = null; wrChallenges(true); render(); };
ACT.wrchal = el => { const c = CHALLENGES.find(x => x.id === el.dataset.id); single(writeItem(S, c, 'challenge'), 'You chose this writing challenge.'); };
ACT.wranalyze = () => {
  const text = $('#wrt').value.trim(); if (tokens(text).length < 12) { toast('Write at least 2–3 sentences.', 'alert'); return; }
  const an = analyzeText(text, { src: 'write' }); WR.an = an; WR.ai = null; WR.text = text;
  creditProduction(text, an, [], { prompt: WR_TYPES[WR.type] }); S.lastWrite = Date.now(); S.analyses.push({ ...an, text: text.slice(0, 400), prompt: WR.type }); if (S.analyses.length > 80) S.analyses.shift();
  applySkill(S, 'writing', clamp(an.levelIdx, 1, 5), an.scores.grammar >= 75, 1); const d = dayStat(); d.min += clamp((Date.now() - (WR.t0 || Date.now())) / 60000, 1, 12); d.n++; WR.t0 = 0; ev('writing_completed', { words: an.words, cefr: an.cefr }); checkAch(); save(); render();
};
ACT.wrai = async el => { const text = $('#wrt').value.trim(); if (tokens(text).length < 12) { toast('Write a bit more first.', 'alert'); return; } el.disabled = true; el.innerHTML = I('sparkles') + ' Reviewing…'; try { WR.ai = await AIService.evaluateWriting(text, { prompt: WR_TYPES[WR.type] }); WR.an = WR.an || analyzeText(text, { src: 'write' }); WR.text = text; render(); } catch (e) { el.disabled = false; el.textContent = 'AI review'; toast(esc(e.message), 'alert'); } };

/* ---------------------- MY MISTAKES ---------------------- */
let MK = { tag: '' };
function repairItem(m) {
  let it = null;
  if (m.cid && /^[gcn]:/.test(m.cid)) it = buildFor(S, m.cid, Math.min((S.c[m.cid] || { tier: 0 }).tier, 2));
  if (!it) it = { kind: 'prod', cid: null, type: 'typed', wtype: 'cloze', tier: 1, lvl: 'B1+', q: 'Correct the mistake:', sub: esc(m.yours), clue: m.why, acc: [m.good], fuzzy: .78, correctText: m.good, why: esc(m.why), ref: m.ref, tag: m.tag };
  it.mistakeId = m.id; it.block = 'repair'; it.reason = `Correction: you missed this ${ago(m.last)} (${m.count}×).`; return it;
}
route(/^\/mistakes$/, () => {
  const pats = errorPatterns(S); const list = S.mist.filter(m => !MK.tag || m.tag === MK.tag).sort((a, b) => b.last - a.last); const due = mistakeDue(S).length;
  return `<div class="ph"><div><h1>My mistakes</h1><p>Your personal error book. Mistakes you make come back at the right time until you stop making them.</p></div><button class="btn primary" data-a="mkrepair" ${S.mist.length ? '' : 'disabled'}>${I('wrench')} Repair ${due || 'my'} mistake${due === 1 ? '' : 's'} now</button></div>
  <div class="card" style="margin-bottom:16px"><h3>Add a correction from class</h3><p class="small muted">Your teacher corrected you? Save it here and the app will bring it back until you stop making it.</p><div class="grid g2" style="margin-top:10px"><div><label class="f">What I said</label><input type="text" id="cls-bad" placeholder="I have 10 years working here" autocomplete="off"></div><div><label class="f">The correct version</label><input type="text" id="cls-good" placeholder="I've been working here for 10 years" autocomplete="off"></div></div><label class="f">Why (optional)</label><input type="text" id="cls-why" placeholder="Duration up to now: present perfect continuous" autocomplete="off"><div style="margin-top:12px"><button class="btn primary" data-a="clsadd">${I('plus')} Save correction</button></div></div>
  ${pats.length ? `<div class="card" style="margin-bottom:16px"><h3>Error memory</h3><p class="small muted">Patterns detected across your answers, writing and speaking.</p><div class="stack" style="margin-top:12px">${pats.slice(0, 6).map(p => `<div class="score-row" style="grid-template-columns:230px 1fr 48px"><span class="b small">${esc(tagName(p.tag))}</span>${bar(p.n / pats[0].n, 'bad')}<b>${p.n}×</b></div>`).join('')}</div></div>` : ''}
  <div class="row wrap" style="margin-bottom:14px"><button class="chip ${MK.tag === '' ? 'on' : ''}" data-a="mkf" data-v="">All (${S.mist.length})</button>${pats.map(p => `<button class="chip ${MK.tag === p.tag ? 'on' : ''}" data-a="mkf" data-v="${esc(p.tag)}">${esc(tagName(p.tag))}</button>`).join('')}</div>
  ${list.length ? `<div class="grid g2">${list.map(m => `<div class="card flat"><div class="row between"><span class="tag st-forgotten">${m.count}× missed</span><span class="tiny muted">${ago(m.last)}</span></div>${m.q ? `<div class="small muted" style="margin-top:10px">${esc(m.q)}</div>` : ''}<div class="mis" style="margin-top:10px"><div class="bad">✗ ${esc(m.yours || '—')}</div><div class="good">✓ ${esc(m.good)}</div></div><p class="small" style="margin-top:8px"><b>Reason:</b> ${esc(m.why || '—')}</p><div style="margin-top:10px">${bar(m.m, 'ok thin')}<div class="row between tiny muted" style="margin-top:6px"><span>Mastery ${pct(m.m)}%</span><span>${m.next <= Date.now() ? 'Review: now' : 'Review in ' + Math.max(1, Math.round((m.next - Date.now()) / DAY)) + ' d'}</span></div></div><div class="row" style="margin-top:12px"><button class="btn sm primary" data-a="mkone" data-id="${m.id}">${I('wrench')} Practice</button><button class="iconbtn" style="width:32px;height:32px" data-a="mkdel" data-id="${m.id}" aria-label="Remove">${I('trash')}</button></div></div>`).join('')}</div>` : `<div class="empty card"><div style="font-size:2rem;color:var(--ok)">${I('check-circle')}</div><p>No mistakes saved${MK.tag ? ' in this group' : ' yet'}. They are recorded automatically as you practice.</p></div>`}`;
});
ACT.clsadd = () => {
  const bad = ($('#cls-bad') || {}).value || '', good = ($('#cls-good') || {}).value || '', why = ($('#cls-why') || {}).value || '';
  if (!bad.trim() || !good.trim()) { toast('Write what you said and the correct version.', 'alert'); return; }
  if (norm(bad) === norm(good)) { toast('The two versions are the same.', 'alert'); return; }
  recordMistake(S, { cid: null, ref: 'class', kind: 'class', tag: 'class', yours: bad.trim(), good: good.trim(), why: why.trim() || 'Correction from your teacher.' });
  save(); toast('Saved. It will come back in your repair sessions.'); render();
};
ACT.mkf = el => { MK.tag = el.dataset.v; render(); };
ACT.mkone = el => { const m = S.mist.find(x => x.id === el.dataset.id); if (m) single(repairItem(m), `Correction: you missed this ${ago(m.last)} (${m.count}×).`); };
ACT.mkdel = el => { const r_ = S.mist.find(x => x.id === el.dataset.id); if (r_) { S.mistDel = S.mistDel || {}; S.mistDel[r_.key] = Date.now(); } S.mist = S.mist.filter(x => x.id !== el.dataset.id); save(); render(); };
ACT.mkrepair = () => { const ms = (mistakeDue(S).length ? mistakeDue(S) : S.mist.slice().sort((a, b) => a.m - b.m)).slice(0, 6); const items = ms.map(repairItem); startRunner({ items, blocks: [{ key: 'repair', label: 'Correction', items }], quick: true }, { kind: 'quick' }); };

/* ---------------------- REVIEW ---------------------- */
route(/^\/review$/, () => {
  const due = dueCounts(); const fc = []; const labs = [];
  for (let i = 0; i < 7; i++) { const a = Date.now() + i * DAY, b = a + DAY; const n = Object.keys(S.c).filter(k => { const c = S.c[k]; return c.seen && !c.prior && (i === 0 ? c.next < b : (c.next >= a && c.next < b)); }).length; fc.push(n); labs.push(i === 0 ? 'Today' : ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'][new Date(a).getDay()]); }
  return `<div class="ph"><div><h1>Reviews due</h1><p>Spaced repetition adjusted to <i>your</i> performance. Easy items wait longer; forgotten ones come back sooner.</p></div></div>
  <div class="grid g21"><div class="card"><div class="row between"><div><div class="stat"><div class="k">Today</div><div class="v">${due.total} items</div><div class="s">Estimated ≈ ${due.minutes} min</div></div></div><button class="btn primary lg" data-a="quick" data-m="review" data-min="${clamp(due.minutes, 3, 15)}" ${due.total ? '' : 'disabled'}>${I('refresh')} Start review</button></div>
  <div class="list" style="margin-top:14px"><div class="it"><div class="ico">${I('book-open')}</div><div class="grow"><b>${due.w} words & phrasal verbs</b></div></div><div class="it"><div class="ico">${I('puzzle')}</div><div class="grow"><b>${due.g} grammar & connector concepts</b></div></div><div class="it"><div class="ico">${I('sparkles')}</div><div class="grow"><b>${due.n} natural-phrasing groups</b></div></div><div class="it"><div class="ico bad">${I('wrench')}</div><div class="grow"><b>${due.m} previous mistakes</b></div></div><div class="it"><div class="ico acc">${I('mic')}</div><div class="grow"><b>${due.sp} speaking challenge</b><div class="small muted">Suggested when you haven't spoken in 3+ days.</div></div></div></div></div>
  <div class="stack"><div class="card"><h4>Next 7 days</h4>${barChart(fc, { labels: labs, h: 150 })}</div><div class="card"><h4>How intervals grow</h4><div class="row wrap" style="margin-top:8px">${['Today', '1d', '3d', '7d', '14d', '30d', '60d'].map(x => `<span class="chip">${x}</span>`).join('')}</div><p class="small muted" style="margin-top:10px">Intervals adapt: a hit with no hints stretches the interval further; a miss shrinks it and moves the concept back one rung on the ladder.</p></div></div></div>`;
});

/* ---------------------- PROGRESS ---------------------- */
let PG = { range: 30 };
function weeklyReport() {
  const now = Date.now(); let mins = 0, nw = 0, act = 0; for (let i = 0; i < 7; i++) { const d = S.days[dayKey(now - i * DAY)]; if (d) { mins += d.min; nw += d.nw || 0; if (d.n) act++; } }
  const mastered = S.ev.filter(e => e.e === 'word_learned' && e.t > now - 7 * DAY).length;
  const keys = Object.keys(S.snap || {}).sort(); const old = keys.filter(k => new Date(k + 'T12:00:00').getTime() <= now - 5 * DAY).pop(); const snap = old ? S.snap[old] : null;
  let gram = null; if (snap) { let best = null; CONTENT.gr.forEach(g => { const c = S.c['g:' + g.id]; if (!c || c.prior) return; const d = pct(mEff(c)) - (snap.g[g.id] || 0); if (d > 0 && (!best || d > best.d)) best = { n: g.name, d }; }); gram = best; }
  let skill = null; if (snap) { SKILLS.forEach(k => { const d = S.sk[k].a - (snap.sk[k] || S.sk[k].a); if (d > 0.02 && (!skill || d > skill.d)) skill = { k, d }; }); }
  const wp = weakPoints(1)[0]; const recent = S.analyses.filter(a => a.at > now - 10 * DAY); const bec = recent.reduce((n, a) => n + ((a.overuse || {}).because || 0), 0), but = recent.reduce((n, a) => n + ((a.overuse || {}).but || 0), 0);
  const acc = (() => { const e = S.ev.filter(x => x.e === 'exercise_answered' && x.t > now - 7 * DAY); return e.length ? e.filter(x => x.ok).length / e.length : null; })();
  let obs = 'Keep going: consistency matters more than long sessions.';
  if (bec + but >= 4) obs = `You're starting to write longer sentences, but you still rely heavily on "because" (${bec}×) and "but" (${but}×). Next week we'll focus on connectors.`;
  else if (daysSince(S.lastSpeak) >= 4) obs = 'You have not spoken in a while. Speaking will be prioritized in your next sessions — B2 is won by spontaneous production.';
  else if (acc != null && acc > .9) obs = 'You are answering almost everything correctly. The engine will raise the difficulty so you keep growing.';
  else if (acc != null && acc < .65) obs = 'This week was demanding. The next sessions will revisit fundamentals before adding new material.';
  return { mins: Math.round(mins), nw, mastered, act, gram, skill, wp, obs, acc };
}
route(/^\/progress$/, () => {
  const N = PG.range; const now = Date.now(); const days = []; for (let i = N - 1; i >= 0; i--) days.push(dayKey(now - i * DAY));
  const sum = (k) => days.reduce((n, d) => n + ((S.days[d] || {})[k] || 0), 0);
  const mins = sum('min'), nAns = sum('n'), okAns = sum('ok'), activeDays = days.filter(d => (S.days[d] || {}).n > 0).length;
  const sess = S.sessions.filter(s => s.at > now - N * DAY).length;
  const agg = N > 30 ? 7 : 1; const mv = [], av = [], lb = [];
  for (let i = 0; i < days.length; i += agg) { const chunk = days.slice(i, i + agg); mv.push(chunk.reduce((n, d) => n + ((S.days[d] || {}).min || 0), 0)); const a = chunk.reduce((n, d) => n + ((S.days[d] || {}).n || 0), 0), o = chunk.reduce((n, d) => n + ((S.days[d] || {}).ok || 0), 0); av.push(a ? o / a * 100 : null); lb.push(chunk[0].slice(5)); }
  const avClean = av.map((v, i, arr) => v == null ? (i ? arr[i - 1] || 0 : 0) : v).filter((v, i) => av[i] != null);
  const spk = S.analyses.filter(a => a.src === 'speak'), wri = S.analyses.filter(a => a.src === 'write');
  const snaps = Object.keys(S.snap || {}).sort().map(k => S.snap[k].a); snaps.push(overallA(S));
  const ws = wordStats(S); const wr = weeklyReport();
  const seenTimes = Object.keys(S.c).filter(k => /^[wp]:/.test(k) && S.c[k].first).map(k => S.c[k].first).sort(); const growth = []; for (let w = 11; w >= 0; w--) { const t = now - w * 7 * DAY; growth.push(seenTimes.filter(x => x <= t).length); }
  const gtop = CONTENT.gr.map(g => ({ g, v: S.c['g:' + g.id] && !S.c['g:' + g.id].prior ? mEff(S.c['g:' + g.id]) : null })).filter(x => x.v != null).sort((a, b) => b.v - a.v);
  const strong = [...gtop.slice(0, 3).map(x => x.g.name), ...(ws.by.mastered ? ['Vocabulary'] : [])].slice(0, 4), weak = weakPoints(4).map(w => w.name);
  return `<div class="ph"><div><h1>Progress</h1><p>What you learned, what you're forgetting, where you improved and where you still slip.</p></div><div class="seg">${[7, 30, 90].map(n => `<button class="${PG.range === n ? 'on' : ''}" data-a="pgrange" data-n="${n}">${n} days</button>`).join('')}</div></div>
  <div class="grid g4" style="margin-bottom:16px"><div class="card stat"><div class="k">Study time</div><div class="v">${Math.round(mins)}<span style="font-size:1rem"> min</span></div><div class="s">${activeDays} active days</div></div><div class="card stat"><div class="k">Sessions</div><div class="v">${sess}</div><div class="s">${nAns} exercises</div></div><div class="card stat"><div class="k">Accuracy</div><div class="v">${nAns ? Math.round(okAns / nAns * 100) : 0}%</div><div class="s">target 80–85%</div></div><div class="card stat"><div class="k">Words met</div><div class="v">${sum('nw')}</div><div class="s">${ws.by.mastered} mastered overall</div></div></div>
  <div class="card" style="margin-bottom:16px;border-color:color-mix(in srgb,var(--acc) 40%,var(--line))"><div class="row between wrap"><h3>${I('calendar')} Your English this week</h3><span class="small muted">auto-generated</span></div><div class="grid g4 keep" style="margin-top:12px"><div><div class="k small muted b">Studied</div><div class="b" style="font-size:1.3rem">${wr.mins} min</div></div><div><div class="k small muted b">New words</div><div class="b" style="font-size:1.3rem">${wr.nw}</div></div><div><div class="k small muted b">Mastered</div><div class="b" style="font-size:1.3rem">${wr.mastered}</div></div><div><div class="k small muted b">Active days</div><div class="b" style="font-size:1.3rem">${wr.act}/7</div></div></div><div class="stack small" style="margin-top:12px">${wr.gram ? `<div>${I('check-circle')} <b>Grammar improved:</b> ${esc(wr.gram.n)} +${wr.gram.d}%</div>` : ''}${wr.skill ? `<div>${I('rocket')} <b>Biggest improvement:</b> ${SKILL_NAME[wr.skill.k]}</div>` : ''}${wr.wp ? `<div>${I('alert')} <b>Needs attention:</b> ${esc(wr.wp.name)}</div>` : ''}<div class="rsub" style="padding:12px 16px;font-size:.98rem">${I('sparkles')} <b>Tutor's observation:</b> “${esc(wr.obs)}”</div></div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h4>Study time ${N > 30 ? '(per week)' : '(per day)'}</h4>${barChart(mv, { labels: lb.map((x, i) => i % Math.ceil(lb.length / 8) === 0 ? x : ''), h: 150, goal: agg === 1 ? S.profile.minutes : null })}</div><div class="card"><h4>Accuracy</h4>${lineChart(av.map(v => v == null ? null : v).filter(v => v != null), { min: 30, max: 100, h: 150 })}</div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h4>Skills by CEFR level</h4>${SKILLS.map(k => `<div class="score-row" style="grid-template-columns:110px 1fr 48px"><span>${SKILL_NAME[k]}</span>${bar(S.sk[k].a / 6)}<b>${lvLabel(S.sk[k].a)}</b></div>`).join('')}</div><div class="card"><h4>CEFR evolution</h4>${lineChart(snaps.slice(-14), { min: 1, max: 5, h: 150, fmt: v => lvLabel(v) })}</div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h4>Vocabulary: passive vs. active</h4><div class="score-row" style="grid-template-columns:150px 1fr 48px"><span>Recognized (passive)</span>${bar(ws.passive / ws.total)}<b>${ws.passive}</b></div><div class="score-row" style="grid-template-columns:150px 1fr 48px"><span>Usable (active)</span>${bar(ws.active / ws.total, 'ok')}<b>${ws.active}</b></div><div class="small muted" style="margin-top:8px">Recognizing a word is not using it. Production exercises convert passive into active.</div><div style="margin-top:14px"><div class="small muted b">Vocabulary growth · last 12 weeks</div>${lineChart(growth, { min: 0, max: Math.max(10, ...growth), h: 110, fmt: v => Math.round(v) })}</div></div>
  <div class="card"><h4>Grammar mastery</h4>${gtop.length ? gtop.slice(0, 9).map(x => `<div class="score-row" style="grid-template-columns:170px 1fr 46px"><span class="small">${esc(x.g.name)}</span>${bar(x.v, x.v > .7 ? 'ok' : x.v < .4 ? 'bad' : '')}<b>${pct(x.v)}%</b></div>`).join('') : '<p class="small muted">Practice grammar to see mastery here.</p>'}</div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h4>Speaking performance</h4>${spk.length >= 2 ? lineChart(spk.slice(-10).map(a => avg(Object.values(a.scores))), { min: 30, max: 100, h: 120 }) : '<p class="small muted" style="margin-top:6px">Complete 2+ speaking tasks.</p>'}</div><div class="card"><h4>Writing level</h4>${wri.length >= 2 ? lineChart(wri.slice(-10).map(a => a.levelIdx), { min: 1, max: 5, h: 120, fmt: v => lvLabel(v) }) : '<p class="small muted" style="margin-top:6px">Analyze 2+ texts in the Writing Lab.</p>'}</div></div>
  <div class="grid g2" style="margin-bottom:16px"><div class="card"><h4 style="color:var(--ok)">Strong topics</h4><div class="row wrap" style="margin-top:8px">${strong.map(s => `<span class="chip on">${esc(s)}</span>`).join('') || '<span class="small muted">Keep practicing</span>'}</div></div><div class="card"><h4 style="color:var(--bad)">Weak topics</h4><div class="row wrap" style="margin-top:8px">${weak.map(s => `<span class="chip">${esc(s)}</span>`).join('') || '<span class="small muted">None detected</span>'}</div></div></div>
  <div class="card"><div class="row between"><h4>Study heatmap · last 13 weeks</h4><span class="small muted">${Object.keys(S.days).filter(k => S.days[k].n > 0).length} days studied in total</span></div><div style="margin-top:10px">${heatmap(13)}</div></div>`;
});
ACT.pgrange = el => { PG.range = +el.dataset.n; render(); };

/* ---------------------- ROADMAP + B2 GATE ---------------------- */
route(/^\/roadmap$/, () => {
  const lv = ['B1', 'B1+', 'B2', 'B2+']; const ph = phase(); const w = whyNotB2(S); const req = w.gate.req;
  const lastTest = l => { const t = S.assess.filter(a => a.type === 'test' && a.testLevel === l).pop(); return t ? `<span class="tag ${t.pass ? 'st-mastered' : 'st-learning'}">${t.pass ? 'Passed' : Math.round(t.acc * 100) + '%'} · ${dateShort(t.at)}</span>` : ''; };
  return `<div class="ph"><div><h1>Roadmap to ${esc(S.profile.target)}</h1><p>Progress is based on <b>demonstrated mastery</b>, not on the number of exercises completed.</p></div><div class="row"><button class="btn" data-a="nav" data-to="/diagnostic">${I('target')} Retake placement test</button></div></div>
  <div class="card" style="margin-bottom:16px"><h3>Level completion</h3><div class="stack" style="margin-top:12px">${lv.map(l => { const p = levelProgress(S, l); return `<div class="score-row" style="grid-template-columns:60px 1fr 52px"><span>${lvTag(l)}</span>${bar(p, p > .8 ? 'ok' : '')}<b>${pct(p)}%</b></div>`; }).join('')}</div><p class="small muted" style="margin-top:8px">Average mastery over all vocabulary, phrasal verbs, grammar, connectors and natural phrasing at that level.</p></div>
  <div class="card" style="margin-bottom:16px"><h3>Your plan</h3><div class="stack" style="margin-top:12px">${ROADMAP.map((r, i) => `<div class="row" style="align-items:flex-start;opacity:${i > ph ? .6 : 1}"><div class="ico ${i < ph ? 'ok' : i === ph ? '' : ''}" style="width:34px;height:34px">${i < ph ? I('check') : i === ph ? I('rocket') : String(i + 1)}</div><div><b>${esc(r.name)}</b> ${i === ph ? '<span class="tag">You are here</span>' : ''}<div class="small muted">${esc(r.desc)}</div></div></div>`).join('')}</div></div>
  <div class="card" style="margin-bottom:16px"><div class="row between wrap"><div><h3>${w.ready ? 'You meet the B2 gate' : esc(w.pct >= .5 ? 'You are approaching B2' : 'Why am I not B2 yet?')}</h3><p class="small muted">Estimated mastery of B2 requirements: <b>${pct(w.pct)}%</b></p></div>${ring(w.pct, 84, 9, 'var(--acc)', pct(w.pct) + '%', 'B2 gate')}</div>
  ${w.ready ? `<div class="fb ok" style="margin-top:12px"><div class="t">${I('trophy')} Requirements met — take the B2 test to confirm</div></div>` : `<div class="sec" style="margin-top:14px"><b class="small">To reach B2 you still need to improve:</b><div class="stack" style="margin-top:8px">${w.low.map(r => `<div class="row" style="align-items:flex-start"><span style="color:var(--acc)">${I('arrow')}</span><div class="grow"><b class="small">${esc(r.name)}</b> <span class="tiny muted">${pct(r.v)}%</span><div class="tiny muted">${esc(r.tip)}</div></div></div>`).join('')}</div></div>`}
  <h4 style="margin-top:18px">All requirements</h4><div class="stack" style="margin-top:8px">${req.list.map(r => `<div class="score-row" style="grid-template-columns:230px 1fr 46px"><span class="small">${esc(r.name)}</span>${bar(r.v, r.v >= .8 ? 'ok' : r.v < .4 ? 'bad' : '')}<b>${pct(r.v)}%</b></div>`).join('')}</div>
  <p class="small muted" style="margin-top:12px">The gate also requires every skill at B2 level (${SKILLS.map(k => SKILL_NAME[k] + ' ' + lvLabel(S.sk[k].a)).join(', ')}) and a passed B2 test (${w.gate.tests ? 'passed ✓' : 'not yet'}).</p></div>
  <div class="card"><h3>CEFR tests</h3><p class="small muted">Longer, non-adaptive assessments with a detailed report by level and skill.</p><div class="grid g4 keep" style="margin-top:12px">${[['B1', 'B1 Test'], ['B1+', 'B1+ Test'], ['B2', 'B2 Test'], ['B2+', 'B2 Advanced']].map(([l, n]) => `<button class="card flat click" style="text-align:left" data-a="nav" data-to="/test/${l}"><div class="ico">${I('flag')}</div><div class="b" style="margin-top:8px">${n}</div><div class="tiny muted">24 questions</div><div style="margin-top:6px">${lastTest(l)}</div></button>`).join('')}</div></div>`;
});

/* ---------------------- AI TUTOR ---------------------- */
const TUT_Q = ['Why am I still B1?', 'Teach me something useful', 'Give me a 5-minute lesson', 'Test my English', 'Explain my biggest mistake', 'Give me B2 vocabulary'];
let TUT = null; const tutAdd = (who, html, plain) => { S.tut = S.tut || []; S.tut.push({ who, html, plain: plain || html.replace(/<[^>]+>/g, ' ') }); if (S.tut.length > 40) S.tut.shift(); };
function tutorBasic(q) {
  const t = norm(q);
  if (/(why|how).*(still|not|close)|what do i need|approaching/.test(t) || /b1|b2/.test(t) && /why|still|need/.test(t)) { const w = whyNotB2(S); return `<b>${w.ready ? 'You meet the B2 criteria.' : 'You are ' + (w.pct >= .5 ? 'approaching B2' : 'building toward B2') + '.'}</b> Estimated mastery of B2 requirements: <b>${pct(w.pct)}%</b>.<br>${w.ready ? 'Take the B2 test to confirm it.' : 'To get there, improve:<ul style="margin:6px 0 0 18px;padding:0">' + w.low.map(r => `<li><b>${esc(r.name)}</b> (${pct(r.v)}%): ${esc(r.tip)}</li>`).join('') + '</ul>'}<div style="margin-top:8px"><button class="btn sm" data-a="nav" data-to="/roadmap">Open roadmap</button></div>`; }
  if (/teach|something|new|learn/.test(t)) return `Here is something chosen for your level and plan.<div style="margin-top:8px"><button class="btn sm primary" data-a="teach">${I('bulb')} Show me</button></div>`;
  if (/5.?min|lesson|session|practice/.test(t)) return `Let's do a focused 5 minutes built from your data.<div style="margin-top:8px"><button class="btn sm primary" data-a="quick" data-m="surprise" data-min="5">${I('play')} Start 5-minute lesson</button></div>`;
  if (/test|quiz|assess/.test(t)) return `A quick 10-question check near your level.<div style="margin-top:8px"><button class="btn sm primary" data-a="nav" data-to="/test/quick">${I('flag')} Start</button></div>`;
  if (/mistake|error|wrong|biggest/.test(t)) { const p = errorPatterns(S)[0]; if (!p) return 'No mistake patterns yet. Practice a bit and I will find them.'; const ex = S.mist.filter(m => m.tag === p.tag).sort((a, b) => b.count - a.count)[0]; return `Your most frequent pattern: <b>${esc(tagName(p.tag))}</b> (${p.n} times).${ex ? `<div class="mis" style="margin-top:8px"><div class="bad">✗ ${esc(ex.yours)}</div><div class="good">✓ ${esc(ex.good)}</div><div class="small muted">${esc(ex.why)}</div></div>` : ''}<div style="margin-top:8px"><button class="btn sm primary" data-a="mkrepair">${I('wrench')} Repair mistakes</button></div>`; }
  if (/vocab|words|b2/.test(t)) { const ws = CONTENT.words.filter(w => lvIdx(w.lvl) >= 4 && stOf('w:' + w.id) !== 'mastered').sort((a, b) => ((S.c['w:' + b.id] ? 1 : 0) - (S.c['w:' + a.id] ? 1 : 0)) || rnd() - .5).slice(0, 6); return `Six B2 words for you:<div class="stack" style="margin-top:8px">${ws.map(w => `<div class="small"><a class="b" style="color:var(--pri);cursor:pointer" data-a="card" data-t="word" data-id="${w.id}">${esc(w.w)}</a> — ${esc(w.pt)}<div class="muted tiny">“${esc(w.ex)}”</div></div>`).join('')}</div>`; }
  if (/connector|because|but|link/.test(t)) return `Instead of “because” try <b>since / as / due to</b>; instead of “but” try <b>however / although / whereas</b>.<div style="margin-top:8px"><button class="btn sm primary" data-a="practiceGroup" data-code="c*">Practice connectors</button></div>`;
  if (/hello|hi\b|hey/.test(t)) return `Hi ${esc(S.profile.name || 'there')}! Ask me why you are not B2 yet, what to learn next, or to test your English.`;
  return null;
}
route(/^\/tutor$/, () => {
  S.tut = S.tut || []; if (!S.tut.length) tutAdd('ai', `Hi ${esc(S.profile.name || 'there')}! I know your level (<b>${overallLabel(S)}</b>), your mistakes and what you are learning. What would you like to do?`);
  return { html: `<div class="ph"><div><h1>AI Tutor</h1><p>${AIService.enabled() ? 'Connected to your AI model: free conversation with full knowledge of your history.' : 'Offline tutor: it answers from your own data. Add an API key in Settings to chat freely with an AI model.'}</p></div></div>
  <div class="card"><div class="chat" id="tchat">${S.tut.map(m => `<div class="msg ${m.who === 'me' ? 'me' : 'ai'}">${m.who === 'me' ? esc(m.plain) : m.html}</div>`).join('')}</div><div class="row wrap" style="margin:10px 0">${TUT_Q.map(q => `<button class="chip" data-a="tq" data-q="${esc(q)}">${esc(q)}</button>`).join('')}</div><div class="row"><input type="text" id="tin" placeholder="Ask your tutor anything…" autocomplete="off"><button class="btn primary" data-a="tsend">${I('send')}</button></div></div>`, after: () => { const i = $('#tin'); i.addEventListener('keydown', e => { if (e.key === 'Enter') ACT.tsend(); }); const c = $('#tchat'); c.scrollTop = c.scrollHeight; window.scrollTo(0, document.body.scrollHeight); } };
});
ACT.tq = el => tutAsk(el.dataset.q);
ACT.tsend = () => { const i = $('#tin'); const q = i.value.trim(); if (q) { i.value = ''; tutAsk(q); } };
async function tutAsk(q) {
  tutAdd('me', esc(q), q); render();
  const off = tutorOffline(q);
  if (off && !(AIService.enabled() && !TUT_Q.includes(q) && norm(q).split(' ').length > 5)) { tutAdd('ai', off); render(); return; }
  if (AIService.enabled()) {
    const hist = S.tut.slice(-12).map(m => ({ role: m.who === 'me' ? 'user' : 'assistant', content: m.plain })); while (hist.length && hist[0].role !== 'user') hist.shift();
    try { const r = await AIService.tutor(hist); tutAdd('ai', esc(r).replace(/\n/g, '<br>').replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')); } catch (e) { tutAdd('ai', 'I could not reach the AI model (' + esc(e.message) + '). ' + (off || 'Try one of the quick questions.')); }
  } else tutAdd('ai', off || 'I can answer from your data: try <b>Why am I still B1?</b>, <b>Teach me something useful</b> or <b>Explain my biggest mistake</b>. For open conversation, add an API key in Settings.');
  save(); render();
}

/* ---------------------- ACHIEVEMENTS ---------------------- */
route(/^\/achievements$/, () => {
  checkAch(); const got = Object.keys(S.ach).length;
  return `<div class="ph"><div><h1>Achievements</h1><p>${got} of ${ACH.length} unlocked · Level ${levelFromXp(S.xp)} · ${S.xp} XP</p></div></div>
  <div class="card" style="margin-bottom:16px"><div class="row between"><b>Level ${levelFromXp(S.xp)}</b><span class="small muted">${S.xp} / ${xpForLevel(levelFromXp(S.xp) + 1)} XP</span></div>${bar((S.xp - xpForLevel(levelFromXp(S.xp))) / (xpForLevel(levelFromXp(S.xp) + 1) - xpForLevel(levelFromXp(S.xp))), 'acc')}</div>
  <div class="badge-grid">${ACH.map(a => { const on = !!S.ach[a.id]; let p = ''; if (!on && a.p) { const [x, y] = a.p(); p = `<div style="margin-top:6px">${bar(x / y, 'thin')}<div class="tiny muted">${x} / ${y}</div></div>`; } return `<div class="ach ${on ? '' : 'locked'}"><div class="ico ${on ? 'acc' : ''}" style="width:46px;height:46px;font-size:1.4rem">${I(a.icon)}</div><div class="grow"><b class="small">${esc(a.name)}</b><div class="tiny muted">${esc(a.desc)}</div>${p}${on ? `<div class="tiny" style="color:var(--ok);margin-top:4px">Unlocked ${dateShort(S.ach[a.id])}</div>` : ''}</div></div>`; }).join('')}</div>`;
});

/* ---------------------- SETTINGS ---------------------- */
route(/^\/settings$/, () => {
  const p = S.profile, s = S.settings; const seg = (key, arr, cur, obj) => `<div class="seg">${arr.map(([v, l]) => `<button class="${String(cur) === String(v) ? 'on' : ''}" data-a="setv" data-o="${obj}" data-k="${key}" data-v="${v}">${l}</button>`).join('')}</div>`;
  return `<div class="ph"><div><h1>Settings</h1><p>Your progress lives on this device and, if you connect sync, in your own Google Drive. Nothing else leaves your browser unless you add an AI key or click an online check.</p></div></div>
  <div class="grid g2"><div class="card"><h3>Study</h3><label class="f">Name</label><input type="text" id="sname" value="${esc(p.name)}"><label class="f">Daily goal</label>${seg('minutes', [[5, '5'], [10, '10'], [15, '15'], [20, '20'], [30, '30']].map(([v, l]) => [v, l + ' min']), p.minutes, 'profile')}<label class="f">I have classes with a teacher</label>${seg('teacher', [['true', 'Yes'], ['false', 'No']], p.teacher ? 'true' : 'false', 'profile')}<div class="field-hint">Yes: less speaking in your daily plan (class covers it) and more vocabulary, listening and reading.</div><label class="f">Target level</label>${seg('target', [['B2', 'B2'], ['B2+', 'B2+'], ['C1', 'C1']], p.target, 'profile')}<label class="f">Preferred topics</label><div class="row wrap">${OB_TOPICS.map(([v, l]) => `<button class="chip ${p.topics.includes(v) ? 'on' : ''}" data-a="settopic" data-v="${v}">${l}</button>`).join('')}</div></div>
  <div class="card"><h3>Audio & language</h3><label class="f">Audio speed</label>${seg('speed', [[.75, '0.75×'], [1, '1×'], [1.15, '1.15×'], [1.25, '1.25×']], s.speed, 'settings')}<label class="f">Accent preference</label>${seg('accent', [['us', 'American'], ['gb', 'British']], s.accent, 'settings')}<label class="f">Portuguese help</label>${seg('ptHelp', [['auto', 'Auto (until B2)'], ['on', 'Always'], ['off', 'Off']], s.ptHelp, 'settings')}<div class="field-hint">Auto: Portuguese + English at B1, 50/50 at B1+, mostly English from B2.</div><label class="f">Theme</label>${seg('theme', [['light', 'Light'], ['dark', 'Dark'], ['system', 'System']], s.theme, 'settings')}<label class="f">Sound effects</label>${seg('sound', [['false', 'Off'], ['true', 'On']], String(!!s.sound), 'settings')}<div class="field-hint">Short chimes for right/wrong answers and finishing a session. Off by default.</div></div>
  <div class="card"><h3>AI features (optional)</h3><p class="small muted">Without a key everything works offline with built-in analysis. With an Anthropic API key you get deeper writing/speaking feedback, a conversational tutor and AI roleplay. The key stays in this browser and requests go directly to Anthropic.</p><label class="f">API key</label><input type="password" id="skey" value="${esc(s.apiKey)}" placeholder="sk-ant-…" autocomplete="off"><label class="f">Model</label><input type="text" id="smodel" value="${esc(s.model)}"><div class="row" style="margin-top:14px"><button class="btn primary" data-a="savekey">${I('check')} Save</button><button class="btn" data-a="testkey">Test connection</button></div><div id="keyres" class="small" style="margin-top:8px"></div></div>
  ${syncCardHTML()}<div class="card"><h3>Your data</h3><p class="small muted">Export a backup, move to another device, or start over.</p>${SERVER ? `<div class="fb ok" style="margin-top:10px;font-size:.88rem"><div class="t" style="font-size:.95rem">${I('check-circle')} Auto-saved to a file on this PC</div><div class="d small">${esc(SERVER.path)}<br>Daily backups are kept in the <b>backups</b> folder next to it.</div></div>` : ''}<div class="stack" style="margin-top:12px"><button class="btn" data-a="export">${I('download')} Export my data (JSON)</button><label class="btn" style="cursor:pointer">${I('upload')} Import data<input type="file" id="imp" accept=".json" style="display:none"></label><button class="btn" data-a="clearhist">${I('trash')} Clear history (events & texts)</button><button class="btn" data-a="demo">${I('eye')} Load demo user</button><button class="btn danger" data-a="resetprog">${I('refresh')} Reset progress</button><button class="btn danger" data-a="delacct">${I('trash')} Delete everything</button></div></div></div>`;
});
ACT.setv = el => { const o = el.dataset.o, k = el.dataset.k; let v = el.dataset.v; if (['minutes', 'speed'].includes(k)) v = +v; if (k === 'sound' || k === 'teacher') v = v === 'true'; S[o][k] = v; if (o === 'profile') S.profileAt = Date.now(); else S.settingsAt = Date.now(); if (k === 'minutes') S.plan = null; if (k === 'theme') applyTheme(); save(); render(); };
ACT.settopic = el => { const a = S.profile.topics, v = el.dataset.v; const i = a.indexOf(v); if (i >= 0) { if (a.length > 1) a.splice(i, 1); } else a.push(v); S.profileAt = Date.now(); save(); render(); };
document.addEventListener('input', e => { if (e.target.id === 'sname') { S.profile.name = e.target.value; S.profileAt = Date.now(); saveSoon(); } });
ACT.savekey = () => { S.settings.apiKey = $('#skey').value.trim(); S.settings.model = $('#smodel').value.trim() || 'claude-haiku-4-5-20251001'; save(); $('#keyres').innerHTML = S.settings.apiKey ? '<span style="color:var(--ok)">Saved.</span>' : 'Key removed. Running offline.'; };
ACT.testkey = async () => { ACT.savekey(); const r = $('#keyres'); if (!AIService.enabled()) { r.textContent = 'Enter a key first.'; return; } r.textContent = 'Testing…'; try { const t = await AIService.call('Reply with the single word OK.', 'ping', { max: 10 }); r.innerHTML = '<span style="color:var(--ok)">Connected: ' + esc(t.trim()) + '</span>'; } catch (e) { r.innerHTML = '<span style="color:var(--bad)">' + esc(e.message) + '</span>'; } };
ACT.export = () => { const blob = new Blob([JSON.stringify(S, NOSAVE, 1)], { type: 'application/json' }); const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'fluent-path-backup-' + today() + '.json'; a.click(); setTimeout(() => URL.revokeObjectURL(a.href), 2000); toast('Backup downloaded.', 'download'); };
document.addEventListener('change', e => { if (e.target.id === 'imp' && e.target.files[0]) { const f = e.target.files[0]; const r = new FileReader(); r.onload = () => { try { const o = JSON.parse(r.result); if (!o || typeof o !== 'object' || Array.isArray(o) || !o.c || typeof o.c !== 'object' || !o.profile || typeof o.profile !== 'object') throw new Error('Not a Fluent Path backup'); if (r.result.length > 20e6) throw new Error('File too large'); delete o.__proto__; if (o.settings) o.settings.apiKey = (S.settings && S.settings.apiKey) || ''; localStorage.setItem(KEY, JSON.stringify(o)); load(); applyTheme(); toast('Data imported.', 'upload'); render(); } catch (err) { toast('Import failed: ' + esc(err.message), 'alert'); } }; r.readAsText(f); } });
ACT.clearhist = () => { if (!confirm('Clear event log, analyses and tutor chat? Progress and mastery are kept.')) return; S.ev = []; S.analyses = []; S.tut = []; save(); toast('History cleared.', 'trash'); render(); };
ACT.demo = () => { if (!confirm('Replace your current data with the demo user?')) return; loadDemo(); applyTheme(); toast('Demo user loaded.', 'eye'); nav('/home'); render(); };
ACT.resetprog = () => { if (!confirm('Reset all progress? Your profile and settings are kept. Drive sync will be disconnected (your Drive copy stays as a backup).')) return; setSyncCfg({ connected: false }); const keep = { profile: S.profile, settings: S.settings, onboarded: true }; const n = newState(); Object.assign(S, n, keep); save(); toast('Progress reset.', 'refresh'); nav('/home'); render(); };
ACT.delacct = () => { if (!confirm('Delete ALL data on this device, including settings and API key?')) return; setSyncCfg({ connected: false }); resetAll(); applyTheme(); location.hash = '/onboarding'; render(); };

/* ---------------------- TRACKS (tópicos) ---------------------- */
const TOPIC_SHOW = { n: 24, t: '' };
ACT.topicmore = () => { TOPIC_SHOW.n += 60; render(); };
route(/^\/topic\/(\w+)$/, m => {
  if (TOPIC_SHOW.t !== m[1]) { TOPIC_SHOW.t = m[1]; TOPIC_SHOW.n = 24; }
  const t = m[1]; const rds = (CONTENT.rd || []).filter(r => r.topic === t); const words = CONTENT.words.filter(w => (w.topics || []).includes(t)); const rps = CONTENT.rp.filter(r => r.topic === t); const lis = CONTENT.lis.filter(l => l.topic === t); const spk = CONTENT.spk.filter(s => s.topic === t);
  const mastered = words.filter(w => stOf('w:' + w.id) === 'mastered').length;
  return `<div class="ph"><div><a class="small muted" href="#/learn">← Learn</a><div class="row" style="margin-top:6px"><div class="ico acc">${I(topicIcon[t] || 'globe')}</div><h1>${esc(TOPIC_LABEL[t] || t)}</h1></div><p>${words.length} words · ${rds.length} readings · ${lis.length} listening · ${rps.length} missions · ${spk.length} speaking prompts</p></div><button class="btn primary" data-a="topicpractice" data-t="${t}">${I('zap')} Practice this track</button></div>
  <div class="card" style="margin-bottom:16px"><div class="row between"><b>Vocabulary mastered</b><span class="small muted">${mastered} / ${words.length}</span></div>${bar(words.length ? mastered / words.length : 0, 'ok')}<div class="row wrap" style="margin-top:12px">${words.slice(0, TOPIC_SHOW.n).map(w => `<button class="chip ${stOf('w:' + w.id) === 'mastered' ? 'on' : ''}" data-a="card" data-t="word" data-id="${w.id}">${esc(w.w)}</button>`).join('')}</div>${words.length > TOPIC_SHOW.n ? `<button class="btn sm" style="margin-top:12px" data-a="topicmore">Show ${Math.min(60, words.length - TOPIC_SHOW.n)} more words</button>` : ''}</div>
  ${rds.length || lis.length ? `<h3 style="margin:18px 0 10px">Read & listen</h3><div class="grid g2">${[...rds.map(x => [x, 'read']), ...lis.map(x => [x, 'listen'])].slice(0, 8).map(([l, mode]) => `<div class="card flat click" data-a="lsstart" data-id="${l.id}" data-mode="${mode}"><div class="row"><div class="ico">${I(mode === 'read' ? 'book' : 'headphones')}</div><div class="grow"><b>${l.title ? esc(l.title) : esc(TOPIC_LABEL[t] || t) + ' · ' + esc(l.kind || mode)}</b><div class="small muted">${mode === 'read' ? 'Reading' : 'Listening'}</div></div>${lvTag(l.lvl)}</div></div>`).join('')}</div>` : ''}
  ${!rds.length && !lis.length && !rps.length && !spk.length ? `<div class="card flat" style="margin-top:16px"><b>This track is vocabulary-only for now.</b><p class="small muted" style="margin-top:6px">Practice the words above, then use Reading, Listening and Speaking in Learn for full passages. New passages for this theme are on the roadmap.</p></div>` : ''}
  ${rps.length ? `<h3 style="margin:18px 0 10px">Real-world missions</h3><div class="grid g2">${rps.map(r => `<div class="card flat click" data-a="rpstart" data-id="${r.id}"><div class="row"><b class="grow">${esc(r.title)}</b>${lvTag(r.lvl)}</div><p class="small muted" style="margin-top:8px">${esc(r.situation)}</p></div>`).join('')}</div>` : ''}
  ${spk.length ? `<h3 style="margin:18px 0 10px">Speaking prompts</h3><div class="grid g2">${spk.slice(0, 6).map(p => `<div class="card flat click" data-a="spstart" data-id="${p.id}"><div class="row"><span class="grow small b">${esc(p.prompt)}</span>${lvTag(p.lvl)}</div></div>`).join('')}</div>` : ''}`;
});
ACT.topicpractice = el => { const t = el.dataset.t; const ws = CONTENT.words.filter(w => (w.topics || []).includes(t)); const A = overallA(S) + .4; const pick_ = ws.map(w => ({ w, s: Math.abs(lvIdx(w.lvl) - A) + rnd() })).sort((a, b) => a.s - b.s).slice(0, 8).map(x => x.w); const items = pick_.map(w => { const c = S.c['w:' + w.id]; const it = wordItem(S, w, c ? Math.min(c.tier, 2) : 1); it.block = 'q'; it.reason = 'Track practice: ' + (TOPIC_LABEL[t] || t); return it; }); startRunner({ items, blocks: [{ key: 'q', label: 'Practice', items }], quick: true }, { kind: 'quick' }); };
